{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "Service",
      "name": "Optical Transceivers for AI Clusters",
      "serviceType": "Optical transceiver, patch cord and switch supply",
      "description": "OSFP and QSFP-DD optical transceivers from 1.6T to 1G, low-loss MPO, MTP and LC patch cords, and InfiniBand and Ethernet switches for H100, H200, B300 and GB300 AI clusters.",
      "image": "https://www.vocom.ai/assets/img/hero/optical-transceivers-range-1920.jpg",
      "url": "https://www.vocom.ai/optical-transceivers",
      "category": "Optical Transceivers",
      "provider": {
        "@id": "https://www.vocom.ai/#organization"
      },
      "areaServed": "Worldwide"
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What transceivers does an NVIDIA B300 cluster need?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In our 32-server reference design: 1.6T modules between the InfiniBand leaf and spine switches, 800G to the eight ConnectX-8 network cards in every server, 400G for north-south Ethernet and fabric management with 400G to 2x 200G breakouts for the BlueField-3 DPUs, 100G and 25G for management, and 10G and 1G at the edge and out-of-band. Send your node count and switch models and we will return the full bill of optics."
          }
        },
        {
          "@type": "Question",
          "name": "Do you supply 1.6T OSFP modules?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. 1.6T and 800G OSFP modules are supplied for GB300 and B300 clusters, including QM3400 InfiniBand switches and ConnectX-8 network cards."
          }
        },
        {
          "@type": "Question",
          "name": "Are your modules compatible with NVIDIA InfiniBand and Ethernet switches?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "They are built to MSA and original-vendor specifications, including heat-dissipating fins, pull-tab color and mechanical dimensions, and they have passed on-site link and interoperability tests in deployed clusters. Send your switch and network card models and we will confirm compatibility part by part."
          }
        },
        {
          "@type": "Question",
          "name": "What is the difference between OSFP and QSFP-DD?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Both are eight-lane form factors for 400G and 800G. OSFP is slightly larger, with more room to shed heat, and is the form factor used for 1.6T. QSFP-DD is backward compatible with QSFP28 cages and is common on Ethernet switches. The port on your switch or network card decides which one you need."
          }
        },
        {
          "@type": "Question",
          "name": "Why buy transceivers from Vocom instead of the switch vendor?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "You get comparable transmission reliability without the brand premium, with full warranty service, and the modules, patch cords and switches come on one order matched port by port."
          }
        },
        {
          "@type": "Question",
          "name": "Do you supply the patch cords and switches as well?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Low-loss MPO, MTP and LC patch cords in custom lengths, and InfiniBand and Ethernet switches from the original vendors, supplied with the modules."
          }
        },
        {
          "@type": "Question",
          "name": "Can you install and configure the cluster network?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, through our partners. Specialist cabling contractors handle hot and cold aisle and cable-tray installation, labeling, bend-radius control and fiber loss testing. System configuration partners handle InfiniBand fabric setup, RoCEv2 congestion control tuning and NCCL performance testing."
          }
        },
        {
          "@type": "Question",
          "name": "What is the lead time and warranty on transceivers?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Both are confirmed with your quote, and lead times are typically in line with our fiber orders. Send the part list to our sales team and we will confirm lead time and warranty for each module."
          }
        },
        {
          "@type": "Question",
          "name": "How fast can I get a quote for optics?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Within 24 hours. Send the GPU platform, node count, switch and network card models, and any patch cord lengths you already know."
          }
        }
      ]
    }
  ]
}

